mapper.select:
SELECT order_no, product_id, sale_id, user_id, status, price
FROM flash_sale
WHERE sale_id = #{saleId,jdbcType=VARCHAR}
  AND user_id = #{userId,jdbcType=VARCHAR}
LIMIT 1

mapper.update:
UPDATE flash_sale
SET status = #{status,jdbcType=VARCHAR}
WHERE order_no = #{orderNo,jdbcType=VARCHAR}
  AND status = #{orgStatus,jdbcType=VARCHAR}
